72	    /** The date of the claim this correction corrects; null when it is not a correction or that claim is not found. */
73	    public void setCorrectedDate(LocalDate correctedDate) { this.correctedDate = correctedDate; }
74	    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects, any other claim's its own. */
75	    public LocalDate getRoundingDate() { return correctedDate != null ? correctedDate : date; }
76	    /** The claim's due-by, fixed when it was created: its date plus the terms of its person's grade in force on that date. */
77	    public LocalDate getDueBy() { return dueBy; }
78	    public void setDueBy(LocalDate dueBy) { this.dueBy = dueBy; }
79	    /** A correction is a claim with a negative amount: its due has no floor and no late charge. */
80	    public boolean isCorrection() { return amount.signum() < 0; }
81	    /** The claim's status log, oldest first: one "<STATUS> by <user> on <date> due=<due>" line per status it has had. */
82	    public java.util.List<String> getLog() { return log; }
83	    public void setLog(java.util.List<String> log) { this.log = log; }
