87	import java.math.BigDecimal;
88	import java.sql.Date;
89	import java.sql.PreparedStatement;
90	import java.sql.Statement;
91	import java.time.LocalDate;
92	import java.util.ArrayList;
93	import java.util.HashMap;
94	import java.util.List;
95	import java.util.Map;
96	import org.springframework.jdbc.core.JdbcTemplate;
97	import org.springframework.jdbc.core.RowMapper;
98	import org.springframework.jdbc.support.GeneratedKeyHolder;
99	import org.springframework.stereotype.Repository;
100	
101	/** The claim store, kept per sheet. */
102	@Repository
103	public class Claims {
104	
105	    private static final RowMapper<Claim> ROW = (rs, i) -> {
106	        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"),
107	                rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(),
108	                rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
109	                rs.getString("claim_number"), rs.getBigDecimal("settled_due"), rs.getString("opened_by"));
110	        claim.setStated(rs.getBoolean("stated"));
111	        claim.setStatedDue(rs.getBigDecimal("stated_due"));
112	        claim.setCorrects(rs.getString("corrects"));
113	        java.sql.Date corrected = rs.getDate("corrected_date");
114	        claim.setCorrectedDate(corrected == null ? null : corrected.toLocalDate());
115	        java.sql.Date dueBy = rs.getDate("due_by");
116	        claim.setDueBy(dueBy == null ? null : dueBy.toLocalDate());
117	        return claim;
118	    };
119	
120	    /** A claim with the date of the claim it corrects (same sheet, same person, by number). */
121	    private static final String SELECT = "SELECT c.*, k.claim_date AS corrected_date FROM claim c LEFT JOIN claim k"
122	            + " ON k.sheet_id = c.sheet_id AND k.person_id = c.person_id AND k.claim_number = c.corrects";
123	
124	    /** The listed_seq after every claim's: a new or moved claim is listed first. */
125	    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(listed_seq), 0) + 1 FROM claim)";
126	
127	    private final JdbcTemplate jdbc;
128	
129	    public Claims(JdbcTemplate jdbc) {
130	        this.jdbc = jdbc;
131	    }
132	
133	    /** The sheet's claims, newest first. */
134	    public List<Claim> list(String sheetId) {
135	        return withLogs(sheetId, jdbc.query(SELECT + " WHERE c.sheet_id = ? ORDER BY c.listed_seq DESC, c.id DESC", ROW, sheetId));
136	    }
137	
138	    /** The claims with their status logs (see {@link ClaimLog}), oldest line first. */
139	    private List<Claim> withLogs(String sheetId, List<Claim> claims) {
140	        Map<Long, List<String>> logs = new HashMap<>();
141	        jdbc.query("SELECT claim_id, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
142	            logs.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
143	                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
144	                            + rs.getDate("log_date").toLocalDate() + " due=" + rs.getString("due"));
145	        }, sheetId);
146	        claims.forEach(claim -> claim.setLog(logs.getOrDefault(claim.getId(), List.of())));
147	        return claims;
148	    }
149	
150	    /** A person's claims on the sheet, newest first. */
151	    public List<Claim> ofPerson(String sheetId, long personId) {
152	        return jdbc.query(SELECT + " WHERE c.sheet_id = ? AND c.person_id = ? ORDER BY c.listed_seq DESC, c.id DESC", ROW, sheetId, personId);
153	    }
154	
155	    public Claim find(String sheetId, long id) {
156	        List<Claim> found = jdbc.query(SELECT + " WHERE c.sheet_id = ? AND c.id = ?", ROW, sheetId, id);
157	        return found.isEmpty() ? null : found.get(0);
158	    }
159	
160	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, LocalDate dueBy) {
161	        return add(sheetId, personId, amount, date, note, null, dueBy);
162	    }
163	
164	    /** Adds a DRAFT claim with its due-by fixed as given. */
165	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
166	            LocalDate dueBy) {
167	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
168	        jdbc.update(con -> {
169	            PreparedStatement ps = con.prepareStatement(
170	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, listed_seq) VALUES (?, ?, ?, ?, ?, ?, ?, "
171	                            + NEXT_LISTED + ")",
172	                    Statement.RETURN_GENERATED_KEYS);
173	            ps.setString(1, sheetId);
174	            ps.setLong(2, personId);
175	            ps.setBigDecimal(3, amount);
176	            ps.setDate(4, Date.valueOf(date));
177	            ps.setString(5, note);
178	            ps.setString(6, corrects);
179	            ps.setDate(7, Date.valueOf(dueBy));
180	            return ps;
181	        }, keys);
182	        Claim claim = new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null);
183	        claim.setCorrects(corrects);
184	        claim.setDueBy(dueBy);
185	        claim.setCorrectedDate(correctedDate(sheetId, personId, corrects));
186	        return claim;
187	    }
188	
189	    /** The date of the person's claim with this number; null when there is none (or no number). */
190	    public LocalDate correctedDate(String sheetId, long personId, String number) {
191	        if (number == null) return null;
192	        List<LocalDate> found = jdbc.query("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ? AND claim_number = ?",
193	                (rs, i) -> rs.getDate(1).toLocalDate(), sheetId, personId, number);
194	        return found.isEmpty() ? null : found.get(0);
195	    }
196	
197	    /** Bind the claim to the figure a statement gives it (stated), or leave it unbound. */
198	    public void bind(Claim claim) {
199	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
200	                claim.isStated(), claim.getStatedDue(), claim.getSheetId(), claim.getId());
201	    }
202	
203	    /** Whether the person has a SETTLED claim with this number on the sheet: one a correction may correct. */
204	    public boolean isSettled(String sheetId, long personId, String number) {
205	        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
206	                + " AND claim_number = ? AND status = ?", Integer.class, sheetId, personId, number, ClaimStatus.SETTLED.name());
207	        return found != null && found > 0;
208	    }
209	
210	    /** Moves the claim to its (new) person, listed as their newest claim, and leaves it unbound. */
211	    public void reassign(Claim claim) {
212	        jdbc.update("UPDATE claim SET person_id = ?, stated = ?, stated_due = ?, listed_seq = " + NEXT_LISTED
213	                + " WHERE sheet_id = ? AND id = ?", claim.getPersonId(), claim.isStated(), claim.getStatedDue(),
214	                claim.getSheetId(), claim.getId());
215	    }
216	
217	    public void save(Claim claim) {
218	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, corrects = ? WHERE sheet_id = ? AND id = ?",
219	                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
220	                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getCorrects(),
221	                claim.getSheetId(), claim.getId());
222	    }
223	}
