225	
226	import java.math.BigDecimal;
227	import java.math.RoundingMode;
228	import java.time.LocalDate;
229	import java.util.LinkedHashMap;
230	import java.util.List;
231	import java.util.Map;
232	import java.util.Objects;
233	import net.officefloor.hq.app.Audit;
234	import net.officefloor.hq.app.claim.Claim;
235	import net.officefloor.hq.app.claim.ClaimResponse;
236	import net.officefloor.hq.app.claim.Claims;
237	import net.officefloor.hq.app.claim.LateCharge;
238	import net.officefloor.hq.app.claim.Rounding;
239	import net.officefloor.hq.app.person.People;
240	import net.officefloor.hq.app.person.Person;
241	import net.officefloor.hq.app.rate.Rates;
242	import net.officefloor.hq.app.setting.Settings;
243	import net.officefloor.hq.app.sheet.Sheets;
244	import org.springframework.stereotype.Service;
245	
246	/**
247	 * The sheet's figures as the screen shows them — each person's claimed and due-total, and the
248	 * sheet's claimed-total and due-total, each person's and the sheet's overdue-total (the dues of their overdue claims, uncapped), each person's due-total held to the sheet's cap — worked out on the server so a change can audit what it
249	 * moved: after the change's own lines, one ROLLUP line per person whose figures changed (people in
250	 * the order they were added; a new person counts as changed), then a TOTALS line when the sheet's
251	 * totals changed.
252	 */
253	@Service
254	public class Rollup {
255	
256	    private static final String NA = "n/a";
257	
258	    private final People people;
259	    private final Claims claims;
260	    private final Rates rates;
261	    private final Sheets sheets;
262	    private final Settings settings;
263	    private final Audit audit;
264	
265	    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings, Audit audit) {
266	        this.people = people;
267	        this.claims = claims;
268	        this.rates = rates;
269	        this.sheets = sheets;
270	        this.settings = settings;
271	        this.audit = audit;
272	    }
273	
274	    /** The sheet's figures now. */
275	    public RollupFigures figures(String sheetId) {
276	        LocalDate today = sheets.today(sheetId);
277	        LocalDate policyDate = settings.policyDate(sheetId);
278	        BigDecimal cap = settings.cap(sheetId);
279	        List<Claim> all = claims.list(sheetId);
280	        Map<Long, RollupFigures.PersonFigures> byPerson = new LinkedHashMap<>();
281	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
282	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
283	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
284	        for (Person person : people.list(sheetId)) {
285	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
286	            BigDecimal due = BigDecimal.ZERO.setScale(2);
287	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
288	            boolean anyFigure = false;
289	            for (Claim claim : all) {
290	                if (claim.getPersonId() != person.getId() || !person.countsLive(claim)) {
291	                    continue;
292	                }
293	                claimed = claimed.add(claim.getAmount());
294	                BigDecimal figure = due(claim, person, today, policyDate);
295	                if (figure != null) {
296	                    anyFigure = true;
297	                    due = due.add(figure);
298	                    if (isOverdue(claim, today)) {
299	                        overdue = overdue.add(figure);
300	                    }
301	                }
302	            }
303	            // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
304	            boolean na = !anyFigure && rates.find(sheetId, person.getGrade(), today) == null;
305	            due = Settings.capped(due, cap);
306	            claimedTotal = claimedTotal.add(claimed);
307	            if (!na) {
308	                dueTotal = dueTotal.add(due);
309	            }
310	            overdueTotal = overdueTotal.add(overdue);
311	            byPerson.put(person.getId(), new RollupFigures.PersonFigures(person.getName(),
312	                    show(claimed), na ? NA : show(due), show(overdue)));
313	        }
314	        return new RollupFigures(byPerson, show(claimedTotal), show(dueTotal), show(overdueTotal));
315	    }
316	
317	    /** A claim's due as the screen shows it now; null for n/a. */
318	    public BigDecimal due(Claim claim, Person person) {
319	        String sheetId = claim.getSheetId();
320	        return due(claim, person, sheets.today(sheetId), settings.policyDate(sheetId));
321	    }
322	
323	    /** A claim's due: fixed when settled or bound by a statement, else its amount (raised to the floor in force on its date) at the rate
324	     *  of its person's grade in force on its date; with its late charge (at the late percent in force on its date) as of today on top. */
325	    private BigDecimal due(Claim claim, Person person, LocalDate today, LocalDate policyDate) {
326	        String sheetId = claim.getSheetId();
327	        RoundingMode rounding = Rounding.of(claim, policyDate);
328	        BigDecimal fixed = ClaimResponse.fixedDue(claim);
329	        BigDecimal figure = fixed != null || claim.isBound() ? fixed
330	                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate()),
331	                        settings.floor(sheetId, claim.getDate()), rounding);
332	        return LateCharge.withCharge(claim, figure, settings.latePct(sheetId, claim.getDate()), today, rounding);
333	    }
334	
335	    /** Audit (on commit) the figures that moved since {@code before}, as taken by {@code user}. */
336	    public void recordChanges(String sheetId, String user, RollupFigures before) {
337	        RollupFigures after = figures(sheetId);
338	        String prefix = " sheet=" + sheetId + " by=" + user;
339	        after.people().forEach((id, now) -> {
340	            RollupFigures.PersonFigures was = before.people().get(id);
341	            if (was == null || !Objects.equals(was.claimed(), now.claimed())
342	                    || !Objects.equals(was.dueTotal(), now.dueTotal())
343	                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
344	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
345	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
346	            }
347	        });
348	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
349	                || !before.overdueTotal().equals(after.overdueTotal())) {
350	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
351	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
352	        }
353	    }
354	
355	    /** A claim is overdue when it is OPEN (or PENDING) and its due-by is before the sheet's today. */
356	    private static boolean isOverdue(Claim claim, LocalDate today) {
357	        return claim.getStatus().isOpen() && claim.getDueBy() != null && claim.getDueBy().isBefore(today);
358	    }
359	
360	    private static String show(BigDecimal value) {
361	        return value.setScale(2).toPlainString();
362	    }
363	}
364	package net.officefloor.hq.app.claim;
365	
366	import java.math.BigDecimal;
367	import java.math.RoundingMode;
368	import net.officefloor.hq.app.period.Periods;
369	import net.officefloor.hq.app.person.People;
370	import net.officefloor.hq.app.rate.Rates;
371	import net.officefloor.hq.app.setting.Settings;
372	import net.officefloor.hq.app.sheet.Sheets;
373	import net.officefloor.plugin.variable.Out;
374	import net.officefloor.plugin.variable.Val;
375	
376	public class ApplyClaimStatus {
377	    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
378	            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, Out<ClaimNumber> number)
379	            throws ClaimStatusRefusedException {
380	        number.set(change(request, claim, sheets, people, rates, periods, settings, numbering));
381	    }
382	
383	    /** Applies a status change to the claim by the rules of a single change, returning its number;
384	     *  throws, leaving the claim as it is, when the change is refused. Bulk settle uses it too. */
385	    static ClaimNumber change(ValidClaimStatus request, Claim claim, Sheets sheets, People people,
386	            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering)
387	            throws ClaimStatusRefusedException {
388	        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
389	        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
390	            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
391	        }
392	        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
393	        if (request.decision() != ValidClaimStatus.Decision.NONE) {
394	            // Only a steward approves or rejects, and only a PENDING claim.
395	            if (claim.getStatus() != ClaimStatus.PENDING) {
396	                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
397	            }
398	            if (!steward) {
399	                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
400	            }
401	        } else if (!claim.getStatus().canBecome(request.target())) {
402	            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
403	        }
404	        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
405	                && claim.getOpenedBy().equals(request.user())) {
406	            // Four eyes: the user who opened a claim cannot settle (or approve) it.
407	            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
408	        }
409	        ClaimStatus target = request.target();
410	        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
411	            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
412	            // a due of n/a is within any limit.
413	            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
414	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
415	            BigDecimal fixed = ClaimResponse.fixedDue(claim);
416	            BigDecimal figure = fixed != null || claim.isBound() ? fixed
417	                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
418	                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
419	            BigDecimal due = LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
420	                    sheets.today(claim.getSheetId()), rounding);
421	            if (limit != null && due != null && due.compareTo(limit) > 0) {
422	                // Above the clerk limit the claim awaits a steward's approval.
423	                target = ClaimStatus.PENDING;
424	            }
425	        }
426	        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
427	            claim.setNumber(numbering.next(claim.getSheetId(), claim.getDate()));
428	            claim.setOpenedBy(request.user());
429	        }
430	        // A voided claim keeps its number; numbers are never reused.
431	        ClaimNumber number = new ClaimNumber(claim.getNumber());
432	        if (target == ClaimStatus.SETTLED) {
433	            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount (raised to the floor)
434	            // at the rate in force on the claim's date, with its late charge as of today frozen in; with no
435	            // figure it stays live (n/a until a rate is set).
436	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
437	            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
438	                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
439	                    settings.floor(claim.getSheetId(), claim.getDate()), rounding);
440	            claim.setSettledDue(LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId(), claim.getDate()),
441	                    sheets.today(claim.getSheetId()), rounding));
442	        }
443	        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
444	        claim.setStatus(target);
445	        return number;
446	    }
447	}
