456	public class AuditClaimStatus {
457	    public void audit(@Val ValidClaimStatus request, @Val Claim claim, @Val ClaimNumber number, People people, Audit audit, @Val RollupFigures before, Rollup rollup, ClaimLog log) {
458	        record(request, claim, number, people, audit, before, rollup, log);
459	    }
460	
461	    /** Logs and audits a status change that went through, as a single change does. Bulk settle uses it too. */
462	    static void record(ValidClaimStatus request, Claim claim, ClaimNumber number, People people, Audit audit, RollupFigures before, Rollup rollup, ClaimLog log) {
463	        String event = switch (request.decision()) {
464	            case APPROVE -> "CLAIM_APPROVED";
465	            case REJECT -> "CLAIM_REJECTED";
466	            case NONE -> switch (claim.getStatus()) {
467	                case OPEN -> "CLAIM_OPENED";
468	                case PENDING -> "CLAIM_PENDING";
469	                case SETTLED -> "CLAIM_SETTLED";
470	                case VOID -> "CLAIM_VOIDED";
471	                case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
472	            };
473	        };
474	        net.officefloor.hq.app.person.Person person = people.find(claim.getSheetId(), claim.getPersonId());
475	        log.record(claim, person, request.user());
476	        String line = ClaimAudit.line(event, request.user(), person, claim, number.value());
477	        if (claim.getStatus() == ClaimStatus.SETTLED) {
478	            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
479	        }
480	        if (request.decision() == ValidClaimStatus.Decision.REJECT) {
481	            line += " reason=" + request.reason();
482	        }
483	        audit.recordOnCommit(line);
484	        rollup.recordChanges(claim.getSheetId(), request.user(), before);
485	    }
486	}
