488	
489	import java.util.List;
490	
491	/** amount is shown with two decimals; status is DRAFT, OPEN, PENDING, SETTLED or VOID; number is "" when none;
492	 *  due is the due fixed when the claim was settled, else (unless PENDING) the figure its person's last statement bound
493	 *  it to, "" while it is live (or bound to n/a); openedBy is "" when never opened; stated is whether
494	 *  the last statement bound it; corrects is the number a correction corrects, "" for any other claim;
495	 *  roundingDate is the date its rounding goes by (a correction's: the date of the claim it corrects);
496	 *  dueBy is the due-by fixed when the claim was created; log is its status log, oldest first (empty unless listed). */
497	public record ClaimResponse(String id, String personId, String amount, String date, String note, String status,
498	        String number, String due, String openedBy, boolean stated, String corrects,
499	        String roundingDate, String dueBy, List<String> log) {
500	
501	    public static ClaimResponse from(Claim claim) {
502	        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
503	                claim.getAmount().setScale(2).toPlainString(), claim.getDate().toString(), claim.getNote(),
504	                claim.getStatus().name(), claim.getNumber() == null ? "" : claim.getNumber(),
505	                fixedDue(claim) == null ? "" : fixedDue(claim).setScale(2).toPlainString(),
506	                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(), claim.isStated(),
507	                claim.getCorrects() == null ? "" : claim.getCorrects(),
508	                claim.getRoundingDate().toString(), claim.getDueBy().toString(), claim.getLog());
509	    }
510	
511	    /** The due a claim keeps whatever the rates do: fixed when settled, else bound by a statement. */
512	    public static java.math.BigDecimal fixedDue(Claim claim) {
513	        if (claim.getSettledDue() != null) return claim.getSettledDue();
514	        return claim.isBound() ? claim.getStatedDue() : null;
515	    }
516	
517	    public static List<ClaimResponse> from(List<Claim> claims) {
518	        return claims.stream().map(ClaimResponse::from).toList();
519	    }
520	}
