537	
538	    private LateCharge() {
539	    }
540	
541	    /** The charge on a claim's figure; zero when it is not overdue or has no figure. */
542	    public static BigDecimal of(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
543	            RoundingMode rounding) {
544	        if (!claim.getStatus().isOpen()) {
