551	    public static BigDecimal asOpen(Claim claim, BigDecimal figure, BigDecimal pct, LocalDate today,
552	            RoundingMode rounding) {
553	        if (figure == null || pct == null || pct.signum() == 0 || claim.isCorrection()) {
554	            return BigDecimal.ZERO.setScale(2);
555	        }
556	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
557	        long periods = overdue > 0 ? overdue / PERIOD_DAYS : 0;
558	        return Rates.due(figure.multiply(BigDecimal.valueOf(periods)), pct, rounding);
